import{_ as t,o,c as s,a4 as a}from"./chunks/framework.DpieW3qv.js";const h=JSON.parse('{"title":"Asset Types Configuration","description":"","frontmatter":{"title":"Asset Types Configuration"},"headers":[],"relativePath":"config/asset.md","filePath":"config/asset.md","lastUpdated":null}'),n={name:"config/asset.md"};function i(d,e,r,c,l,g){return o(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="asset-types-configuration" tabindex="-1">Asset Types Configuration <a class="header-anchor" href="#asset-types-configuration" aria-label="Permalink to &quot;Asset Types Configuration&quot;">​</a></h1><p>Where asset type definitions live and how they relate to slot resolution.</p><hr><h2 id="two-config-files" tabindex="-1">Two config files <a class="header-anchor" href="#two-config-files" aria-label="Permalink to &quot;Two config files&quot;">​</a></h2><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><strong><code>src/config/asset.config.js</code></strong></td><td><strong>Source of truth</strong> for asset types and patterns. Defines <code>ASSET_TYPES</code>, <code>ZONE_TEMPLATE_VARIANTS</code>, <code>TEMPLATE_PATTERNS</code>, <code>ASSET_TYPE_PATTERNS</code>, and <code>HOMEPAGE_ZONE_PATTERNS</code>.</td></tr><tr><td><strong><code>src/config/slots.config.js</code></strong></td><td>Imports from <code>asset.config.js</code> and adds <strong>resolution helpers</strong> (e.g. <code>resolveAssetType</code>, <code>getSyncStrategy</code>, <code>getHtmlSource</code>). Used by the rest of the app for slot resolution and behavior.</td></tr></tbody></table><p>When you add or change an asset type, you edit <strong>asset.config.js</strong>. The slots config re-exports and derives from it.</p><hr><h2 id="what-lives-in-asset-config-js" tabindex="-1">What lives in asset.config.js <a class="header-anchor" href="#what-lives-in-asset-config-js" aria-label="Permalink to &quot;What lives in asset.config.js&quot;">​</a></h2><ul><li><strong>ASSET_TYPES</strong> — Each key (PPH, POPUP, HOMEPAGE, PLP_HEADER, etc.) has: <code>active</code>, <code>mode</code>, <code>syncStrategy</code>, <code>slot</code>, <code>template</code>, optional <code>zones</code>, <code>externalResources</code>, <code>categoryMapping</code>, <code>contextIdByBrand</code>, etc.</li><li><strong>ZONE_TEMPLATE_VARIANTS</strong> — Template variants per zone (e.g. HP_HERO variants).</li><li><strong>TEMPLATE_PATTERNS</strong> — Regex patterns mapping wireframe/Excel names to template paths.</li><li><strong>ASSET_TYPE_PATTERNS</strong> — Regex patterns mapping Excel asset type strings to canonical keys (e.g. DISCLAIMER → POPUP, FP → PLP_PROMO).</li><li><strong>HOMEPAGE_ZONE_PATTERNS</strong> — Maps standalone Excel types (e.g. CAT A, SLOT 1) into HOMEPAGE zone keys so they merge into the homepage asset.</li></ul><hr><h2 id="what-lives-in-slots-config-js" tabindex="-1">What lives in slots.config.js <a class="header-anchor" href="#what-lives-in-slots-config-js" aria-label="Permalink to &quot;What lives in slots.config.js&quot;">​</a></h2><ul><li>Imports <code>ASSET_TYPES</code>, <code>getAssetTypeConfig</code>, <code>isActive</code>, and the pattern arrays from <code>asset.config.js</code>.</li><li>Defines <strong>resolution and helper functions</strong> used by ExcelParser, RenderingEngine, OcapiPayload, etc.: <code>resolveAssetType</code>, <code>getSyncStrategy</code>, <code>resolveSlotConfig</code>, <code>getHomepageZoneKey</code>, <code>isMultiZone</code>, and others.</li><li>Builds <strong>SLOT_REGISTRY</strong> and related structures for the runtime.</li></ul><p>So: <strong>definitions</strong> in asset.config, <strong>resolution and API</strong> in slots.config.</p><hr><h2 id="adding-a-new-asset-type" tabindex="-1">Adding a new asset type <a class="header-anchor" href="#adding-a-new-asset-type" aria-label="Permalink to &quot;Adding a new asset type&quot;">​</a></h2><ol><li><strong>Add the type</strong> in <strong>asset.config.js</strong> under <code>ASSET_TYPES</code> (active, mode, syncStrategy, slot, template, and any zones or categoryMapping).</li><li><strong>If Excel uses different names,</strong> add entries to <code>ASSET_TYPE_PATTERNS</code> in asset.config.js (order matters).</li><li><strong>If it merges into HOMEPAGE,</strong> add an entry to <code>HOMEPAGE_ZONE_PATTERNS</code> in asset.config.js.</li><li><strong>If mode is TEMPLATE,</strong> add a template under <code>templates/{type}/template.html</code>.</li><li><strong>Test:</strong> Run <code>make excel</code> (or point to your Excel) and <code>make build</code> for a date that includes the new type.</li></ol><p>See <a href="/ocapi-docs.github.io/concepts/asset-types-guide.html#adding-a-new-asset-type">Asset Types Guide</a> for step-by-step and code snippets.</p><hr><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/config/slots.html">Slots &amp; Asset Types</a> — Schema and slot binding details</li><li><a href="/ocapi-docs.github.io/concepts/asset-types-guide.html">Asset Types Guide</a> — Adding a new type and Excel → slot mapping</li><li><a href="/ocapi-docs.github.io/guides/templates.html">Template Authoring</a> — How templates use asset and zone data</li></ul>',20)])])}const f=t(n,[["render",i]]);export{h as __pageData,f as default};
